--shadow-none: none;
--shadow-sm: 0 0 0 1px rgba(255,255,255,0.08);
--shadow-md: 0 1px 3px rgba(0,0,0,0.50);     /* 미디어 카드 */
--shadow-lg: 0 8px 24px rgba(0,0,0,0.60);    /* 모달 */
--shadow-xl: 0 20px 48px rgba(0,0,0,0.70);
--duration-fast: 100ms;
--duration-base: 200ms;
--duration-slow: 350ms;
--ease-out: cubic-bezier(0, 0, 0.2, 1);
--ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}
:root {
  /* Primary - X White (다크 캔버스의 풀필 액센트는 흰색) */
  --color-primary-50:  #0A0A0A;
  --color-primary-100: #16181C;
  --color-primary-200: #2F3336;
  --color-primary-300: #3E4144;
  --color-primary-400: #71767B;
  --color-primary-500: #FFFFFF;  /* X White — 검정 캔버스 위 풀필 액션 */
  --color-primary-600: #FFFFFF;
  --color-primary-700: #FFFFFF;
  --color-primary-800: #FFFFFF;
  --color-primary-900: #FFFFFF;

  /* Secondary - Action Blue (트위터 잔재, 링크용) */
  --color-secondary-500: #1D9BF0;

  /* Action accents (점적 사용) */
  --color-action-like:    #F91880;
  --color-action-retweet: #00BA7C;
  --color-action-bookmark:#1D9BF0;

  /* Neutral - 다크 반전 램프 (0=검정 → 1000=흰색) */
  --color-neutral-0:    #000000;
  --color-neutral-50:   #0A0A0A;
  --color-neutral-100:  #16181C;
  --color-neutral-200:  #1E2024;
  --color-neutral-300:  #2F3336;
  --color-neutral-500:  #3E4144;
  --color-neutral-700:  #71767B;
  --color-neutral-800:  #9AA0A6;
  --color-neutral-900:  #E7E9EA;
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크 캔버스에서 가독 */
  --color-success-bg: #0E2A1C;
  --color-success-fg: #4BD18E;
  --color-warning-bg: #2E2410;
  --color-warning-fg: #E0A82E;
  --color-error-bg:   #2C1316;
  --color-error-fg:   #F6606C;
  --color-info-bg:    #0E2233;
  --color-info-fg:    #4FB3F2;

  /* Surface (Dark) */
  --bg-base:     #000000;
  --bg-subtle:   #16181C;
  --bg-elevated: #000000;
